import json,csv
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
R=Path(__file__).resolve().parents[1];O=R/'结果'
def table(rows,keys):
 def fmt(x):return f'{x:.4f}' if isinstance(x,float) else str(x)
 return '| '+' | '.join(keys)+' |\n| '+' | '.join(['---']*len(keys))+' |\n'+'\n'.join('| '+' | '.join(fmt(r.get(k,'')) for k in keys)+' |' for r in rows)+'\n'
def main():
 e=json.loads((O/'evaluation.json').read_text(encoding='utf-8'));f=json.loads((R/'frozen_evaluation.json').read_text(encoding='utf-8'));p=json.loads((R/'结果/preparation.json').read_text(encoding='utf-8'))
 lines=['# A4：异常原因辅助监督与专家知识引导的阶段性检验','## 结论摘要','异常原因辅助监督学到了可预测的问题类型信息，但本轮没有证明它能稳定补充正常品相知识。A4a有局部AUROC与误报改善信号，AP下降且默认阈值清洗漏检增加；A4b没有显示相对A3的稳定增量。两组均未达到测试前预设的多种子扩展门槛。本轮按两个seed42实验收束，后续优先研究同类别、相近正常品相的局部参照比较，而非继续增加全局分类头。','## 研究问题与继承边界','最终目标是把人类专家知识引入钱币异常检测。本轮只检验问题类型标签是否为共享视觉特征提供增量监督，不把增加分类头等同于注入专家的观察规则。类别／版别、正常保存状态／品相、异常问题类型是三个不同标签体系。','A0 为共享骨干的单面 logit max；A1 为双面全局特征拼接 MLP；A2 推理使用真实类别 Embedding，属于条件输入而非本轮图像输入方案；A3 只监督正常币品相；A3b 扩展到异常币品相，但没有获得一致优势。本轮分别以 A1 与 A3 为直接基线，未加载其训练后权重，也未继承 A3b 的监督变化。','## 设计、标签与公平控制','A4a = A1 + Linear(1536,4) 原因头，L=BCE+0.1×原因损失。A4b = A3 + 相同原因头，L=BCE+0.2×正常品相CE+0.1×原因损失。品相CE仍仅在具有有效 A3 品相标签的正常样本内求均值；所有异常币品相均不监督。原因类别依次为正常、92、97、98；异常必须恰有一个对应代码，其他异常只参与BCE。','原因权重只由训练集计算：w_c=N_train/(4*n_c)，加权CE求和除以完整批次样本数，不按批次权重总和重新归一化。这样一个完整训练轮中四类的名义权重总量完全相同，避免普通逆频率CE在小批次内重新归一化造成尺度波动。权重约为0.3394、1.6928、5.6489、7.2862，原因损失系数固定0.1；不做参数搜索。',table([{'split':s,**v['reason_counts']} for s,v in p.items()],['split','0','1','2','3','-1']),'表中0=正常、1=92、2=97、3=98、-1=不监督原因。类别权重由训练集决定，验证／测试统计仅用于审计。','共享ConvNeXt-Tiny、384分辨率、双面768维拼接、1536→256→1异常头、ImageNet权重、seed42、batch8、独立±10°旋转、AdamW主干2e-5/头1e-4、WD0.01、AMP、梯度裁剪5均沿用。15–50轮、早停patience10和ReduceLROnPlateau均沿用。新原因头用隔离的seed1042初始化；逐张量检查A4a原参数与A1、A4b原参数与A3相等。各轮采样及增强种子保持一致，实际停止轮数由共同验证规则决定。上限和早停规则一致不等于实际优化步数相同；更长训练和更多候选轮次的验证选择也限制单种子归因，不能把差异全部解释为专家知识学习。推理forward只接收双面图像。','原始划分与双面配对不变，所有A3原始清单字段逐项相等。复用SSD原图缓存，没有改写缓存或历史实验。详见结果/data_verification.json、implementation_verification.json。','运行恢复：A4a第2轮因宿主内存压力出现长时间停顿，保留完整第1轮检查点后恢复。两组统一使用2个训练worker、0个验证worker，原配置为4+4；模型与优化、batch、逐样本增强种子、逐轮采样种子、早停规则不变。首次未完成的第2轮不计入有效训练预算，恢复记录见结果/resource_recovery.json。耗时为有效轮次累计，不含中断重做和最终评估。','## 训练和验证选择']
 for n in ['A4a','A4b']:
  c=json.loads((R/n/'结果/TRAIN_COMPLETE.json').read_text(encoding='utf-8'));lines.append(f"{n}：完成{c['epochs']}轮，最佳第{c['best_epoch']}轮，累计训练/验证/保存{c['training_seconds']/60:.2f}分钟。")
 lines+=['仅按验证二分类AUROC选best，最大验证F1选阈值并列取最高值。召回阈值为满足70%、75%、A1原验证召回77.3869%、80%、85%、90%的最高验证阈值。统一先冻结四模型阈值、权重哈希、多种子判断，再推理A4测试集；测试已用于历史探索，本报告全部测试结论为探索性冻结评估。','多种子预设判断：相对直接基线验证AUROC至少增加0.005且主召回要求下FP不增加，才建议后续配对种子确认。本轮按两个核心seed42实验收束，验证判断在测试推理前保存：',table([{'model':n,**v} for n,v in f['decision'].items()],['model','baseline','val_auroc_delta','val_primary_fp_delta','paired_multiseed_worth_followup']),'## 整体指标',table(e['comparison'],['split','model','auroc','ap','f1','precision','recall','fp','fn','threshold']),'## 相近异常召回要求','以下阈值全部取自验证。验证召回要求相同不意味着测试实际召回相同，应同时比较FP、FN与实际Recall。所有预设点完整列出，避免挑选工作点。',table(e['matched_recall'],['split','model','target','recall','fp','fn','f1']),'## 异常代码的独立区分能力','每种异常仅与同集合全部正常币比较，使用原二分类头分数计算AUROC；不把原因头多分类准确率当作二分类能力。AP受各子集异常比例影响。小样本代码只作描述，不能据一两枚样本泛化。',table(e['codes'],['split','model','code','normal_n','abnormal_n','auroc','ap']),'## 正常品相误报与异常原因漏检','默认验证F1工作点：grade为正常误报FP，code为异常漏检FN。',table([x for x in e['groups'] if x['op']=='F1' and (x['kind']=='grade' or x['group'] in ['92','97','98'])],['split','model','kind','group','n','errors','rate']),'主召回要求77.3869%工作点：',table([x for x in e['groups'] if x['op']==str(154/199) and (x['kind']=='grade' or x['group'] in ['92','97','98'])],['split','model','kind','group','n','errors','rate']),'其余召回点的完整品相与代码分组见结果/group_errors.csv。','## 原因头是否具有实际区分作用',table(e['aux'],['split','model','accuracy','macro_f1','balanced_accuracy','reason92_recall','reason97_recall','reason98_recall']),'结果/A4*_reason_diagnostic.json保存四类混淆矩阵、各类precision/recall/F1、一对其余AUROC及多数类基线。若原因头能预测问题标签，只能说明共享特征保留了相关信息；还必须由二分类分代码AUROC、等验证召回FP及漏检变化证明增量价值。两者不可混同，也不能由标签预测断定模型已经学会专家关注部位或物理成因。','## 不确定性',table(e['bootstrap'],['split','model','baseline','auroc_delta','ci025','ci975']),'区间来自2000次按正常/异常分层的配对整币bootstrap，同一次重采样用于两模型。它反映当前固定模型的样本波动，不能代替配对多种子，不能覆盖训练随机性、同来源照片相关性或已使用测试集的选择偏差。','## 结果解释与明确结论',((O/'interpretation.md').read_text(encoding='utf-8') if (O/'interpretation.md').exists() else '<!-- INTERPRETATION -->'),'## 后续专家知识引导路线','1. 先将三个标签体系分开维护：类别／版别定义设计及工艺参照，正常品相描述保存状态，问题代码描述异常类型。不能将低品相自动当异常，也不能用问题代码替代品相。A2只是使用类别编号，并未编码专家知识，不能据A2结果否定类别知识的价值。','2. 优先验证同类别正常币的局部参照比较：对齐正反面和对应部位，在相近保存状态、成像条件下比较局部纹理与结构。币种特定的正常参照可能需要区分图案细节、文字/边齿、浮雕高点、底板和工艺特征；哪些部位在特定版别属于正常差异，必须由可信资料和专家核实后再制定规则。','3. 清洗漏检的候选假设包括局部细纹被384缩放和全局池化削弱、成像光照改变表面线索、正常磨耗与异常处理的视觉重叠。这些均为待验证假设，本实验分数和代码不能确定具体原因。可设计专家盲审与原分辨率局部对照，先核实证据是否在图像中可见，再讨论局部表示。','4. 正常AU/XF误报更适合先检验同类、相近品相参照是否解释疑似区域；对于只有局部证据的疑似损伤，先比较相应部位，不继续凭全局分类头数量推断知识增加。候选规则仅是待检验提问：异常纹理是否跨越该版别本来应有的结构？疑似磨耗是否能由同类正常品相参照解释？不同光照下证据是否稳定？本轮未进行资料核实，不将其写成确定的钱币鉴定知识。','5. 下一阶段若开展专家知识验证，应先在训练/验证材料上定义部位、正常参照与评价方案，再使用新的未参与探索的独立测试集。按本轮用户范围，不在A4中建立知识库、检索系统或独立复核网络。','![训练曲线与冻结阈值召回对照](结果/training_and_recall.png)','## 文件与复现','A4a与A4b各自保存代码/train.py、模型/config.json、best.pt、last.pt、threshold.json、reason_mapping.json，及结果中的清单、历史、日志、验证/测试预测。根目录protocol.json为实验预设；frozen_evaluation.json为测试前冻结记录。代码/run_training.py可按last.pt恢复未完成训练；完成标记存在则跳过。代码/evaluate.py顺序执行freeze、infer、analyze（freeze禁止在测试预测已存在后执行），代码/report.py与代码/interpret.py顺序生成本报告。所有训练与分析使用原配置中的Python环境。','结果/error_transitions.csv保留相对A1/A3及两A4之间的逐币纠错/新增错误，可用于后续盲审抽样，未用于参数选择。历史文件哈希复核见结果/final_verification.json。']
 report_text='\n\n'.join(lines)+'\n'
 start=report_text.index('## 后续专家知识引导路线');end=report_text.index('![训练曲线',start)
 route=report_text[start:end];report_text=report_text[:start]+report_text[end:]+'\n'+route
 (R/'实验报告.md').write_text(report_text,encoding='utf-8')
 fig,axs=plt.subplots(1,2,figsize=(11,4))
 for n in ['A4a','A4b']:
  h=json.loads((R/n/'结果/history.json').read_text(encoding='utf-8'));axs[0].plot([r['epoch'] for r in h],[r['val_auroc'] for r in h],label=n)
 for n in ['A1','A3','A4a','A4b']:
  rows=[x for x in e['matched_recall'] if x['split']=='test' and x['model']==n];axs[1].plot([x['recall'] for x in rows],[x['fp'] for x in rows],'-o',label=n)
 axs[0].set(xlabel='Epoch',ylabel='Validation AUROC');axs[1].set(xlabel='Actual test recall (validation thresholds)',ylabel='Normal false positives')
 for ax in axs:ax.legend();ax.grid(alpha=.2)
 fig.tight_layout();fig.savefig(O/'training_and_recall.png',dpi=180);plt.close(fig)
if __name__=='__main__':main()
